-- Initial, non-destructive schema. Applied idempotently by Database.initialize().
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users(telegram_id INTEGER PRIMARY KEY, username TEXT, first_name TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, last_active_at TEXT, is_blocked INTEGER NOT NULL DEFAULT 0, free_limit_override INTEGER);
CREATE TABLE IF NOT EXISTS plans(id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, price INTEGER NOT NULL DEFAULT 0, currency TEXT NOT NULL DEFAULT 'XTR', duration_days INTEGER NOT NULL DEFAULT 30, daily_limit INTEGER, monthly_limit INTEGER, features TEXT NOT NULL DEFAULT '', max_slides INTEGER NOT NULL DEFAULT 10, allow_pdf INTEGER NOT NULL DEFAULT 0, allow_pptx INTEGER NOT NULL DEFAULT 1, examples_limit INTEGER NOT NULL DEFAULT 0, tests_limit INTEGER NOT NULL DEFAULT 0, ai_model TEXT, is_active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS subscriptions(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(telegram_id), plan_id INTEGER NOT NULL REFERENCES plans(id), status TEXT NOT NULL, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, payment_id INTEGER, reminder_sent INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_subscriptions_user_status ON subscriptions(user_id,status,ends_at);
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(telegram_id), plan_id INTEGER NOT NULL REFERENCES plans(id), provider TEXT NOT NULL, provider_charge_id TEXT UNIQUE, invoice_payload TEXT NOT NULL UNIQUE, amount INTEGER NOT NULL, currency TEXT NOT NULL, status TEXT NOT NULL, test_mode INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, confirmed_at TEXT, refunded_at TEXT);
CREATE TABLE IF NOT EXISTS usage_records(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(telegram_id), feature TEXT NOT NULL, tokens INTEGER, success INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_usage_user_time ON usage_records(user_id,created_at);
CREATE TABLE IF NOT EXISTS promo_codes(code TEXT PRIMARY KEY, plan_id INTEGER NOT NULL REFERENCES plans(id), discount_percent INTEGER NOT NULL DEFAULT 0, starts_at TEXT, ends_at TEXT, max_uses INTEGER, uses INTEGER NOT NULL DEFAULT 0, is_active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS promo_redemptions(code TEXT NOT NULL REFERENCES promo_codes(code), user_id INTEGER NOT NULL REFERENCES users(telegram_id), redeemed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(code,user_id));
CREATE TABLE IF NOT EXISTS admin_audit_logs(id INTEGER PRIMARY KEY AUTOINCREMENT, admin_id INTEGER NOT NULL, action TEXT NOT NULL, target_user_id INTEGER, details TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS system_settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT OR IGNORE INTO schema_migrations(version) VALUES(1);
